    if n == 0:
        return "no more bottles"
    if n == 1:
        return "1 bottle"
    return f"{n} bottles"


def _verse(n):
    first = f"{_bottles(n)} of beer on the wall, {_bottles(n)} of beer."
    if n == 0:
        second = "Go to the store and buy some more, 99 bottles of beer on the wall."
        first = first[0].upper() + first[1:]
    else:
        it = "it" if n == 1 else "one"
        second = (f"Take {it} down and pass it around, "
                  f"{_bottles(n - 1)} of beer on the wall.")
    return [first, second]


def recite(start, take=1):
    lines = []
    for i in range(take):
        if i:
            lines.append("")
        lines.extend(_verse(start - i))
    return lines
